<?php
declare(strict_types=1);

final class AgentHubApp
{
    private $repo;
    private $config;
    private $basePath;

    public function __construct()
    {
        $this->config = agenthub_config();
        $this->repo = new AgentHubRepository(agenthub_pdo(), $this->config);
        $this->repo->migrate();
        $this->basePath = normalize_base_path((string)($this->config['base_path'] ?? ''));
        if (session_status() !== PHP_SESSION_ACTIVE) {
            $sessionDir = __DIR__ . '/../storage/sessions';
            if (!is_dir($sessionDir)) @mkdir($sessionDir, 0700, true);
            if (is_dir($sessionDir) && is_writable($sessionDir)) ini_set('session.save_path', $sessionDir);
            session_start(['cookie_httponly'=>true, 'cookie_samesite'=>'Lax', 'cookie_secure'=>isset($_SERVER['HTTPS']) && $_SERVER['HTTPS'] !== 'off']);
        }
    }

    public function run()
    {
        $path = request_path($this->basePath);
        $method = strtoupper($_SERVER['REQUEST_METHOD'] ?? 'GET');
        try {
            if ($method === 'OPTIONS') { http_response_code(204); return; }
            if ($path === '/api/health' && $method === 'GET') return $this->json(['ok'=>true,'status'=>'ready','version'=>$this->config['version'],'started_at'=>gmdate('Y-m-d\TH:i:s.u\Z')]);
            if ($path === '/' && $method === 'GET') return $this->page();
            if ($path === '/messages' && $method === 'GET') return $this->page();
            if ($path === '/history' && $method === 'GET') return $this->historyPage();
            if ($path === '/guide' && $method === 'GET') return $this->guidePage();
            if ($path === '/admin/login' && $method === 'POST') return $this->login();
            if ($path === '/admin/logout' && $method === 'POST') { $this->requireAdmin(); $this->requireCsrf(); session_destroy(); return $this->redirect('/'); }
            if ($path === '/api/agents' && $method === 'GET') return $this->json($this->repo->agents());
            if ($path === '/api/agents' && $method === 'POST') { $body = $this->jsonBody(['name'], ['transfer_url'=>'', 'transfer_token'=>'']); return $this->json($this->repo->registerAgent((string)$body['name'], (string)$body['transfer_url'], (string)$body['transfer_token']), 201); }
            if ($path === '/api/messages' && $method === 'GET') return $this->getMessages();
            if ($path === '/api/messages' && $method === 'POST') return $this->json($this->repo->addMessage($this->jsonBody(['sender','target','content','attachments'], ['attachments'=>[]])), 201);
            if (preg_match('#^/api/messages/(\d+)$#', $path, $match) && $method === 'DELETE') { $this->requireAdmin(); $this->requireCsrf(); $this->repo->deleteMessage((int)$match[1]); http_response_code(204); return; }
            if ($path === '/api/history' && $method === 'GET') { $this->requireAdmin(); return $this->json($this->repo->history((string)($_GET['date'] ?? ''), (string)($_GET['agent'] ?? ''), (int)($_GET['limit'] ?? 100))); }
            if ($path === '/api/files' && $method === 'POST') { $this->error(410, 'file persistence is disabled; use the direct data channel'); return; }
            if ($path === '/api/transfers' && $method === 'POST') { $this->requireAdmin(); $this->requireCsrf(); return $this->json($this->repo->relayTransfer((string)($_GET['agent'] ?? ''), (string)($_GET['name'] ?? $_SERVER['HTTP_X_AGENTHUB_FILENAME'] ?? ''), (string)($_SERVER['CONTENT_TYPE'] ?? 'application/octet-stream')), 201); }
            if (preg_match('#^/api/files/([^/]+)$#', $path, $match) && $method === 'GET') return $this->download(rawurldecode($match[1]));
            $this->error(404, 'not found');
        } catch (InvalidArgumentException $error) { $this->error(400, $error->getMessage()); }
          catch (RuntimeException $error) { $this->error(strpos($error->getMessage(), 'not found') !== false ? 404 : 500, $error->getMessage()); }
          catch (Throwable $error) { error_log('AgentHub error: ' . $error->getMessage()); $this->error(500, 'internal server error'); }
    }

    private function getMessages(): void
    {
        $agent = trim((string)($_GET['agent'] ?? '')); $after = filter_var($_GET['after'] ?? 0, FILTER_VALIDATE_INT, ['options'=>['min_range'=>0]]);
        if ($after === false) throw new InvalidArgumentException('after must be a non-negative integer');
        if ($agent === '') $this->requireAdmin();
        $this->json($this->repo->messages($agent, (int)$after));
    }

