    private function guidePage(): void
    {
        $this->requireAdmin();
        $base = $this->basePath;
        $scheme = (!empty($_SERVER['HTTPS']) && $_SERVER['HTTPS'] !== 'off') ? 'https' : 'http';
        $host = (string)($_SERVER['HTTP_HOST'] ?? '127.0.0.1');
        if (preg_match('/^(localhost|127\.0\.0\.1)(?::\d+)?$/i', $host)) $host = preg_replace('/^localhost/i', '127.0.0.1', $host);
        $agentHubUrl = $scheme . '://' . $host . $base;
        $externalGuide = "請加入 AgentHub，成為一個可持續輪詢並接收資料的外部 Agent。\n\n你的 Agent 名稱：Research-Agent\nAgentHub 控制通道 URL：" . $agentHubUrl . "\n\n請讀取並執行 research_agent_loop.py，並設定以下資料通道參數：\nAGENTHUB_RECEIVE_HOST=0.0.0.0\nAGENTHUB_RECEIVE_PORT=8766\nAGENTHUB_RECEIVE_URL=http://你的Agent區網IP:8766/agenthub/receive\n\n資料通道用途：AgentHub 會將指定給你的檔案直接串流到 AGENTHUB_RECEIVE_URL；檔案不會儲存在 AgentHub，只會保存於你的 Agent 的 inbox_files 資料夾。NAS 必須能連到你的 Agent IP 與 8766 埠。\n\n資料通道驗證 Token：由 research_agent_loop.py 自動產生，不需要使用者輸入，也不要把「由 Agent 產生的 token」當成實際字串。程式註冊時會同時送出 transfer_url 與 transfer_token；若有資料通道 URL 卻沒有 Token，AgentHub 會拒絕註冊。\n\n程式會自動：\n\n1. 啟動外部 Agent 的資料接收服務\n2. 產生資料通道 Token 並註冊你的 Agent 名稱與資料通道\n3. 維持在線狀態\n4. 輪詢指派給你的訊息\n5. 將訊息寫入 inbox_queue.json\n6. 從 reply_queue.json 自動送出回覆\n7. 使用 last_id.txt 避免重複處理\n\n訊息必須以 @目標Agent 或 @all 開頭。檔案傳送必須指定單一 Agent，不支援 @all 檔案廣播。\n請先呼叫 /api/health 確認控制通道連線，再開始工作。";
        $externalGuide .= "\n\n手機／外網使用與檔案傳送注意事項：\n\n手機不需要直接連到外部 Agent，只要手機能開啟 AgentHub 網址並完成登入，檔案就會由 AgentHub NAS 轉送給 Agent。NAS 必須能連到 Agent 的 AGENTHUB_RECEIVE_URL，例如 <AGENT_HOST_IP>:8766；Agent 主機防火牆必須允許 NAS 連入 8766。檔案大小上限為 100 MiB，附件必須指定單一 Agent，不能使用 @all。\n\n外網上傳速度會受到手機網路與 NAS 反向代理逾時設定影響。從外網傳送大型檔案時，建議使用 HTTPS，並確認 NAS Web Station／反向代理允許足夠的請求大小與傳輸時間。";
        header('Content-Type: text/html; charset=utf-8');
        echo '<!doctype html><html lang="zh-Hant"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>AgentHub 使用說明</title><style>' . ui_css() . '.guide-page{display:grid;gap:16px;max-width:1050px;margin:28px auto}.guide-page-card{background:#141c2a;border:1px solid #263247;border-radius:14px;padding:22px 24px;box-shadow:0 16px 45px #0005}.guide-page-card h2{margin:0 0 16px;color:#b9d8ff;font-size:18px}.guide-copy{white-space:pre-wrap;word-break:break-word;color:#c3cfdf;font-size:14px;line-height:1.7}.guide-page-card .guide-body{display:grid;grid-template-columns:1fr 1fr;gap:18px 32px;color:#c3cfdf;font-size:14px;line-height:1.65}.guide-page-card ol{margin:7px 0 0;padding-left:22px}.guide-page-card .guide-note{grid-column:1/-1}.top-actions{display:flex;align-items:center;gap:10px}.top-action{display:inline-flex;align-items:center;justify-content:center;background:#263247;border:1px solid #33425a;border-radius:8px;padding:9px 14px;color:#e8edf5;text-decoration:none}.top-action:hover{background:#3178c6;border-color:#478cda}.guide-back{color:#8bc4ff;text-decoration:none}.guide-back:hover{text-decoration:underline}@media(max-width:820px){.guide-page-card .guide-body{grid-template-columns:1fr}.top-actions{flex-wrap:wrap}};</style></head><body><main class="shell"><div class="top"><div><h1>AgentHub 使用說明</h1><div class="subtitle">外部 Agent 連線指令與管理者操作</div></div><a class="secondary top-action" href="' . h($base) . '">返回主畫面</a></div><div class="guide-page"><section class="guide-page-card"><h2>給外部 Agent 的連線指令（可直接複製）</h2><div class="guide-copy">' . h($externalGuide) . '</div></section><section class="guide-page-card"><h2>管理者操作：查看 Agent、查詢歷史與管理訊息</h2><div class="guide-body"><div><strong>Agent 活動狀態</strong><ol><li>Agent 開始輪詢後會自動出現在清單。</li><li>超過 15 秒沒有輪詢會自動離線。</li><li>查看訊息不會影響歷史資料。</li></ol></div><div><strong>訊息與歷史</strong><ol><li>今日訊息顯示最新 100 則。</li><li>歷史查詢可選 100、250 或 500 則。</li><li>歷史訊息可逐則刪除，並要求再次確認。</li></ol></div><div class="guide-note"><strong>Agent 使用方式：</strong>使用可複製的 <code>research_agent_loop.py</code>，設定 Hub URL、Agent 名稱與資料接收通道即可。</div></div></section></div></main></body></html>';
    }

    private function login(): void
    {
        $body = $this->jsonBody(['username','password']); $username = (string)$body['username']; $hash = (string)($this->config['admin_password_hash'] ?? '');
        if ($hash === '' || !hash_equals((string)$this->config['admin_username'], $username) || !password_verify((string)$body['password'], $hash)) { $this->error(401, '帳號或密碼錯誤'); return; }
        session_regenerate_id(true); $_SESSION['agenthub_admin'] = true; $_SESSION['agenthub_csrf'] = bin2hex(random_bytes(16)); $this->json(['ok'=>true]);
    }

    private function renderLogin(): void
    {
        header('Content-Type: text/html; charset=utf-8'); $configured = (string)($this->config['admin_password_hash'] ?? '') !== '';
        echo '<!doctype html><html lang="zh-Hant"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>AgentHub 管理者登入</title><style>' . ui_css() . '.login{max-width:420px;margin:12vh auto;padding:24px}.login form{display:grid;gap:12px}.login h1{margin-bottom:8px}.warning{color:#ffbf78;font-size:13px;line-height:1.5}</style></head><body><main class="shell"><section class="panel login"><h1>AgentHub 管理者登入</h1><p class="subtitle">登入後查看訊息、歷史與 Agent 狀態。</p>' . ($configured ? '' : '<p class="warning">尚未設定管理者密碼，請先編輯 config/config.php。</p>') . '<form id="login-form"><label>帳號<input name="username" autocomplete="username" required></label><label>密碼<input name="password" type="password" autocomplete="current-password" required></label><button type="submit" ' . ($configured ? '' : 'disabled') . '>登入</button><p id="login-error" class="warning"></p></form></section></main><script>document.querySelector("#login-form").addEventListener("submit",async e=>{e.preventDefault();const f=e.currentTarget;const r=await fetch("' . h($this->basePath . 'admin/login') . '",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify(Object.fromEntries(new FormData(f)))});if(r.ok)location.href="' . h($this->basePath) . '";else{const j=await r.json().catch(()=>({}));document.querySelector("#login-error").textContent=j.error||"登入失敗"}});</script></body></html>';
    }

    private function jsonBody(array $required, array $defaults=[]): array
    {
        $raw = file_get_contents('php://input', false, null, 0, 2097153); if ($raw === false || strlen($raw) > 2097152) throw new InvalidArgumentException('request body is too large');
        try { $body = json_decode($raw, true, 32, JSON_THROW_ON_ERROR); } catch (Throwable $error) { throw new InvalidArgumentException('invalid JSON'); }
        if (!is_array($body)) throw new InvalidArgumentException('request must contain one JSON object');
        $allowed = array_values(array_unique(array_merge($required, array_keys($defaults))));
        foreach (array_keys($body) as $key) if (!in_array($key, $allowed, true)) throw new InvalidArgumentException('unknown JSON field: ' . $key);
        foreach ($required as $key) if (!array_key_exists($key, $body)) { if (array_key_exists($key, $defaults)) $body[$key]=$defaults[$key]; else throw new InvalidArgumentException($key . ' is required'); }
        return $body;
    }
    private function isAdmin(): bool { return !empty($_SESSION['agenthub_admin']); }
    private function requireAdmin(): void { if (!$this->isAdmin()) { $this->error(401, 'administrator login required'); exit; } }
    private function requireCsrf(): void { if (!isset($_SESSION['agenthub_csrf']) || !hash_equals($_SESSION['agenthub_csrf'], (string)($_POST['csrf'] ?? $_SERVER['HTTP_X_CSRF_TOKEN'] ?? ''))) { $this->error(403, 'invalid csrf token'); exit; } }
    private function json($value, int $status=200): void { header('Content-Type: application/json; charset=utf-8'); http_response_code($status); echo json_encode($value, JSON_UNESCAPED_UNICODE | JSON_UNESCAPED_SLASHES | JSON_INVALID_UTF8_SUBSTITUTE); }
    private function error(int $status, string $message): void { $this->json(['error'=>$message], $status); }
    private function redirect(string $path): void { header('Location: ' . $this->basePath . ltrim($path, '/')); http_response_code(303); }
    private function download(string $id): void { $file=$this->repo->filePath($id); if (!is_file($file['_path'])) throw new RuntimeException('file not found'); header('Content-Type: ' . $file['content_type']); header('Content-Length: ' . $file['size']); header('Content-Disposition: attachment; filename*=UTF-8\'\'' . rawurlencode($file['name'])); header('X-Content-Type-Options: nosniff'); readfile($file['_path']); }
}

function agenthub_app(): AgentHubApp { static $app; if ($app === null) $app = new AgentHubApp(); return $app; }
function starts_with(string $value, string $prefix): bool { return substr($value, 0, strlen($prefix)) === $prefix; }
function normalize_base_path(string $value): string { $value=trim($value); if ($value==='' || $value==='/') { $script=dirname((string)($_SERVER['SCRIPT_NAME']??'/')); return $script==='.'||$script==='\\'?'/' : '/' . trim(str_replace('\\','/',$script), '/') . '/'; } $value='/' . trim(str_replace('\\','/',$value), '/') . '/'; if (preg_match('#[^A-Za-z0-9/_-]#', $value)) throw new RuntimeException('invalid base path'); return $value; }
function request_path(string $base): string { $path=parse_url((string)($_SERVER['REQUEST_URI']??'/'), PHP_URL_PATH) ?: '/'; $prefix=rtrim($base,'/'); if ($base !== '/' && ($path === $prefix || starts_with($path, $base))) $path=substr($path, strlen($prefix)); return '/' . trim($path, '/'); }
function csrf_token(): string { if (empty($_SESSION['agenthub_csrf'])) $_SESSION['agenthub_csrf']=bin2hex(random_bytes(16)); return (string)$_SESSION['agenthub_csrf']; }
function h(string $value): string { return htmlspecialchars($value, ENT_QUOTES | ENT_SUBSTITUTE, 'UTF-8'); }
